qualified_questions.sparql_query:
PREFIX BO: <http://example.org/BO#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?property
WHERE {
  ?property rdf:type owl:DatatypeProperty ;
            rdfs:domain BO:SimpleTypeVariable ;
            rdfs:range xsd:boolean .
  FILTER(?property = BO:isDataList)
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?simpleTypeVariable ?property
WHERE {
  ?simpleTypeVariable a BO:SimpleTypeVariable ;
                      BO:isDataList "true"^^xsd:boolean ;
                      ?property ?value .
  FILTER(?property IN (BO:hasDataRestriction, BO:hasDataRestriction_minInclusive, BO:hasDataRestriction_maxInclusive, BO:hasDataRestriction_minExclusive, BO:hasDataRestriction_maxExclusive, BO:hasDataRestriction_minLength, BO:hasDataRestriction_maxLength, BO:hasDataRestriction_pattern, BO:hasValue, BO:oneM2MAttribute, BO:oneM2MTargetURI, BO:hasDataType, BO:hasThingAnnotation))
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?restrictionType ?range
WHERE {
  ?restrictionType rdfs:subPropertyOf BO:hasDataRestriction ;
                   rdfs:domain BO:SimpleTypeVariable .
  OPTIONAL { ?restrictionType rdfs:range ?range . }
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?property ?value
WHERE {
  ?simpleTypeVariable a BO:SimpleTypeVariable ;
                      BO:oneM2MAttribute ?oneM2MAttributeValue ;
                      ?property ?value .
  FILTER(?property != BO:oneM2MAttribute)
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?property
WHERE {
  ?property rdfs:subPropertyOf BO:hasDataRestriction ;
            rdfs:domain BO:SimpleTypeVariable ;
            rdfs:range xsd:nonNegativeInteger .
  FILTER(?property = BO:hasDataRestriction_maxLength || ?property = BO:hasDataRestriction_minLength || ?property = BO:hasDataRestriction_length)
}

PREFIX BO: <http://example.org/BO#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?class
WHERE {
  ?class owl:disjointWith BO:SimpleTypeVariable
}

PREFIX BO: <http://example.org/BO#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?class
WHERE {
  BO:SimpleTypeVariable owl:disjointWith ?class
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?range
WHERE {
  BO:refersTo rdfs:range ?range
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?type
WHERE {
  BO:Function rdf:type ?type
}

PREFIX bo: <http://example.org/BO#>
SELECT ?domain
WHERE {
  bo:refersTo rdfs:domain ?domain.
}

SELECT ?classType
WHERE {
  BO:GET_InputDataPoint rdf:type ?classType .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT (COUNT(?function) AS ?count)
WHERE {
  ?function rdf:type BO:ControllingFunction ;
            BO:hasCommand ?command .
  FILTER EXISTS { ?function BO:hasCommand ?specificCommand }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?areaNetwork
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyPhysicalStandard ?physicalStandard ;
               BO:netTechnologyCommunicationProtocol ?communicationProtocol .
  FILTER(?physicalStandard = "specific_physical_standard" && ?communicationProtocol = "particular_communication_protocol")
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?versionIRI
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> owl:versionIRI ?versionIRI .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?versionIRI
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> rdf:type owl:Ontology ;
  owl:versionIRI ?versionIRI .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?ontology
WHERE {
  ?ontology rdf:type owl:Ontology ;
            owl:versionIRI <https://git.onem2m.org/MAS/BaseOntology/raw/3_6_0/base_ontology.owl> .
}
